using Silk.NET.OpenGL;

namespace Meitou.Rendering.Gpu;

/// <summary>The OpenGL backend of <see cref="IGl"/>: every call goes straight to the context, so the pictures are OpenGL's own.</summary>
public sealed unsafe class GlPassthrough(GL gl) : IGl
{
    /// <summary>The wrapped context (screenshots and the viewer's own drawing use it directly).</summary>
    public GL Gl => gl;

    public void Enable(EnableCap cap) => gl.Enable(cap);
    public void Disable(EnableCap cap) => gl.Disable(cap);
    public void Viewport(int x, int y, uint width, uint height) => gl.Viewport(x, y, width, height);
    public void Scissor(int x, int y, uint width, uint height) => gl.Scissor(x, y, width, height);
    public void DepthMask(bool flag) => gl.DepthMask(flag);
    public void DepthFunc(DepthFunction func) => gl.DepthFunc(func);
    public void ColorMask(bool red, bool green, bool blue, bool alpha) => gl.ColorMask(red, green, blue, alpha);
    public void BlendFunc(BlendingFactor sfactor, BlendingFactor dfactor) => gl.BlendFunc(sfactor, dfactor);
    public void CullFace(TriangleFace mode) => gl.CullFace(mode);
    public void FrontFace(FrontFaceDirection mode) => gl.FrontFace(mode);
    public void PolygonMode(TriangleFace face, PolygonMode mode) => gl.PolygonMode(face, mode);
    public void PolygonOffset(float factor, float units) => gl.PolygonOffset(factor, units);
    public void ClearColor(float red, float green, float blue, float alpha) => gl.ClearColor(red, green, blue, alpha);
    public void ClearDepth(double depth) => gl.ClearDepth(depth);
    public void Clear(ClearBufferMask mask) => gl.Clear(mask);
    public void PixelStore(PixelStoreParameter pname, int param) => gl.PixelStore(pname, param);
    public GLEnum GetError() => gl.GetError();
    public void GetInteger(GLEnum pname, out int data) => gl.GetInteger(pname, out data);
    public void GetInteger(GetPName pname, out int data) => gl.GetInteger(pname, out data);
    public void GetInteger(GetPName pname, int* data) => gl.GetInteger(pname, data);
    public void Finish() => gl.Finish();
    public uint CreateShader(ShaderType type) => gl.CreateShader(type);
    public void ShaderSource(uint shader, string source) => gl.ShaderSource(shader, source);
    public void CompileShader(uint shader) => gl.CompileShader(shader);
    public void GetShader(uint shader, ShaderParameterName pname, out int @params) => gl.GetShader(shader, pname, out @params);
    public string GetShaderInfoLog(uint shader) => gl.GetShaderInfoLog(shader);
    public void DeleteShader(uint shader) => gl.DeleteShader(shader);
    public uint CreateProgram() => gl.CreateProgram();
    public void AttachShader(uint program, uint shader) => gl.AttachShader(program, shader);
    public void LinkProgram(uint program) => gl.LinkProgram(program);
    public void GetProgram(uint program, ProgramPropertyARB pname, out int @params) => gl.GetProgram(program, pname, out @params);
    public string GetProgramInfoLog(uint program) => gl.GetProgramInfoLog(program);
    public void DeleteProgram(uint program) => gl.DeleteProgram(program);
    public void UseProgram(uint program) => gl.UseProgram(program);
    public int GetUniformLocation(uint program, string name) => gl.GetUniformLocation(program, name);
    public uint GetUniformBlockIndex(uint program, string uniformBlockName) => gl.GetUniformBlockIndex(program, uniformBlockName);
    public void UniformBlockBinding(uint program, uint uniformBlockIndex, uint uniformBlockBinding) => gl.UniformBlockBinding(program, uniformBlockIndex, uniformBlockBinding);
    public void Uniform1(int location, int v0) => gl.Uniform1(location, v0);
    public void Uniform1(int location, float v0) => gl.Uniform1(location, v0);
    public void Uniform2(int location, float v0, float v1) => gl.Uniform2(location, v0, v1);
    public void Uniform3(int location, float v0, float v1, float v2) => gl.Uniform3(location, v0, v1, v2);
    public void Uniform4(int location, float v0, float v1, float v2, float v3) => gl.Uniform4(location, v0, v1, v2, v3);
    public void Uniform1(int location, uint count, float* value) => gl.Uniform1(location, count, value);
    public void Uniform2(int location, uint count, float* value) => gl.Uniform2(location, count, value);
    public void Uniform3(int location, uint count, float* value) => gl.Uniform3(location, count, value);
    public void Uniform4(int location, uint count, float* value) => gl.Uniform4(location, count, value);
    public void UniformMatrix4(int location, uint count, bool transpose, float* value) => gl.UniformMatrix4(location, count, transpose, value);
    public uint GenBuffer() => gl.GenBuffer();
    public void DeleteBuffer(uint buffer) => gl.DeleteBuffer(buffer);
    public void BindBuffer(BufferTargetARB target, uint buffer) => gl.BindBuffer(target, buffer);
    public void BindBufferBase(BufferTargetARB target, uint index, uint buffer) => gl.BindBufferBase(target, index, buffer);
    public void BufferData(BufferTargetARB target, nuint size, void* data, BufferUsageARB usage) => gl.BufferData(target, size, data, usage);
    public void BufferData<T>(BufferTargetARB target, ReadOnlySpan<T> data, BufferUsageARB usage) where T : unmanaged => gl.BufferData<T>(target, data, usage);
    public void BufferSubData(BufferTargetARB target, nint offset, nuint size, void* data) => gl.BufferSubData(target, offset, size, data);
    public uint GenVertexArray() => gl.GenVertexArray();
    public void DeleteVertexArray(uint array) => gl.DeleteVertexArray(array);
    public void BindVertexArray(uint array) => gl.BindVertexArray(array);
    public void EnableVertexAttribArray(uint index) => gl.EnableVertexAttribArray(index);
    public void VertexAttribPointer(uint index, int size, VertexAttribPointerType type, bool normalized, uint stride, void* pointer) => gl.VertexAttribPointer(index, size, type, normalized, stride, pointer);
    public void VertexAttribIPointer(uint index, int size, VertexAttribIType type, uint stride, void* pointer) => gl.VertexAttribIPointer(index, size, type, stride, pointer);
    public void VertexAttribDivisor(uint index, uint divisor) => gl.VertexAttribDivisor(index, divisor);
    public void DrawArrays(PrimitiveType mode, int first, uint count) => gl.DrawArrays(mode, first, count);
    public void DrawArraysInstanced(PrimitiveType mode, int first, uint count, uint instancecount) => gl.DrawArraysInstanced(mode, first, count, instancecount);
    public void DrawElements(PrimitiveType mode, uint count, DrawElementsType type, void* indices) => gl.DrawElements(mode, count, type, indices);
    public void DrawElementsInstanced(PrimitiveType mode, uint count, DrawElementsType type, void* indices, uint instancecount) => gl.DrawElementsInstanced(mode, count, type, indices, instancecount);
    public uint GenTexture() => gl.GenTexture();
    public void DeleteTexture(uint texture) => gl.DeleteTexture(texture);
    public void ActiveTexture(TextureUnit texture) => gl.ActiveTexture(texture);
    public void BindTexture(TextureTarget target, uint texture) => gl.BindTexture(target, texture);
    public void TexParameter(TextureTarget target, TextureParameterName pname, int param) => gl.TexParameter(target, pname, param);
    public void TexParameter(TextureTarget target, TextureParameterName pname, float param) => gl.TexParameter(target, pname, param);
    public void TexParameter(TextureTarget target, TextureParameterName pname, ReadOnlySpan<float> @params) => gl.TexParameter(target, pname, @params);
    public void TexImage2D(TextureTarget target, int level, InternalFormat internalformat, uint width, uint height, int border, PixelFormat format, PixelType type, void* pixels) => gl.TexImage2D(target, level, internalformat, width, height, border, format, type, pixels);
    public void TexImage2D<T>(TextureTarget target, int level, InternalFormat internalformat, uint width, uint height, int border, PixelFormat format, PixelType type, ReadOnlySpan<T> pixels) where T : unmanaged => gl.TexImage2D<T>(target, level, internalformat, width, height, border, format, type, pixels);
    public void TexSubImage2D(TextureTarget target, int level, int xoffset, int yoffset, uint width, uint height, PixelFormat format, PixelType type, void* pixels) => gl.TexSubImage2D(target, level, xoffset, yoffset, width, height, format, type, pixels);
    public void TexSubImage2D<T>(TextureTarget target, int level, int xoffset, int yoffset, uint width, uint height, PixelFormat format, PixelType type, ReadOnlySpan<T> pixels) where T : unmanaged => gl.TexSubImage2D<T>(target, level, xoffset, yoffset, width, height, format, type, pixels);
    public void CompressedTexImage2D(TextureTarget target, int level, InternalFormat internalformat, uint width, uint height, int border, uint imageSize, void* data) => gl.CompressedTexImage2D(target, level, internalformat, width, height, border, imageSize, data);
    public void CompressedTexImage3D(TextureTarget target, int level, InternalFormat internalformat, uint width, uint height, uint depth, int border, uint imageSize, void* data) => gl.CompressedTexImage3D(target, level, internalformat, width, height, depth, border, imageSize, data);
    public void CompressedTexSubImage2D(TextureTarget target, int level, int xoffset, int yoffset, uint width, uint height, InternalFormat format, uint imageSize, void* data) => gl.CompressedTexSubImage2D(target, level, xoffset, yoffset, width, height, format, imageSize, data);
    public void CompressedTexSubImage3D(TextureTarget target, int level, int xoffset, int yoffset, int zoffset, uint width, uint height, uint depth, InternalFormat format, uint imageSize, void* data) => gl.CompressedTexSubImage3D(target, level, xoffset, yoffset, zoffset, width, height, depth, format, imageSize, data);
    public void GenerateMipmap(TextureTarget target) => gl.GenerateMipmap(target);
    public uint GenFramebuffer() => gl.GenFramebuffer();
    public void DeleteFramebuffer(uint framebuffer) => gl.DeleteFramebuffer(framebuffer);
    public void BindFramebuffer(FramebufferTarget target, uint framebuffer) => gl.BindFramebuffer(target, framebuffer);
    public void FramebufferTexture2D(FramebufferTarget target, FramebufferAttachment attachment, TextureTarget textarget, uint texture, int level) => gl.FramebufferTexture2D(target, attachment, textarget, texture, level);
    public void FramebufferRenderbuffer(FramebufferTarget target, FramebufferAttachment attachment, RenderbufferTarget renderbuffertarget, uint renderbuffer) => gl.FramebufferRenderbuffer(target, attachment, renderbuffertarget, renderbuffer);
    public GLEnum CheckFramebufferStatus(FramebufferTarget target) => gl.CheckFramebufferStatus(target);
    public void DrawBuffer(DrawBufferMode buf) => gl.DrawBuffer(buf);
    public void ReadBuffer(ReadBufferMode src) => gl.ReadBuffer(src);
    public void BlitFramebuffer(int srcX0, int srcY0, int srcX1, int srcY1, int dstX0, int dstY0, int dstX1, int dstY1, ClearBufferMask mask, BlitFramebufferFilter filter) => gl.BlitFramebuffer(srcX0, srcY0, srcX1, srcY1, dstX0, dstY0, dstX1, dstY1, mask, filter);
    public void ReadPixels(int x, int y, uint width, uint height, PixelFormat format, PixelType type, void* pixels) => gl.ReadPixels(x, y, width, height, format, type, pixels);
    public void ReadPixels<T>(int x, int y, uint width, uint height, PixelFormat format, PixelType type, Span<T> pixels) where T : unmanaged => gl.ReadPixels<T>(x, y, width, height, format, type, pixels);
    public uint GenRenderbuffer() => gl.GenRenderbuffer();
    public void DeleteRenderbuffer(uint renderbuffer) => gl.DeleteRenderbuffer(renderbuffer);
    public void BindRenderbuffer(RenderbufferTarget target, uint renderbuffer) => gl.BindRenderbuffer(target, renderbuffer);
    public void RenderbufferStorage(RenderbufferTarget target, InternalFormat internalformat, uint width, uint height) => gl.RenderbufferStorage(target, internalformat, width, height);
    public void RenderbufferStorageMultisample(RenderbufferTarget target, uint samples, InternalFormat internalformat, uint width, uint height) => gl.RenderbufferStorageMultisample(target, samples, internalformat, width, height);
    public uint GenQuery() => gl.GenQuery();
    public void DeleteQuery(uint id) => gl.DeleteQuery(id);
    public void QueryCounter(uint id, QueryCounterTarget target) => gl.QueryCounter(id, target);
    public void BeginQuery(QueryTarget target, uint id) => gl.BeginQuery(target, id);
    public void EndQuery(QueryTarget target) => gl.EndQuery(target);
    public void GetQueryObject(uint id, QueryObjectParameterName pname, out int @params) => gl.GetQueryObject(id, pname, out @params);
    public void GetQueryObject(uint id, QueryObjectParameterName pname, out ulong @params) => gl.GetQueryObject(id, pname, out @params);
}
